#!/usr/bin/env sage
"""Test translation-norm image ranks on q=13 split matching orbits."""


# This file was *autogenerated* from the file notes/2026-07-26-c665-q13-norm-images.sage
from sage.all_cmdline import *   # import sage library

_sage_const_13 = Integer(13); _sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_5 = Integer(5); _sage_const_2 = Integer(2); _sage_const_364 = Integer(364); _sage_const_1092 = Integer(1092); _sage_const_2184 = Integer(2184)
import importlib.util
from pathlib import Path

from sage.all import GF, matrix


HERE = Path(__file__).resolve().parent
Q = _sage_const_13 
F = GF(Q)


def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


BASE = load("c665_base", HERE / "2026-07-26-c665-balanced-matching-completeness.py")


def translation_permutation():
    return tuple(list(range(_sage_const_1 , Q)) + [_sage_const_0 , Q])


def norm_record(orbit, sheets):
    base_product = BASE.matching_product(orbit[_sage_const_0 ], Q)
    points = []
    for matching in orbit:
        product = BASE.matching_product(matching, Q)
        difference = {
            exponent: (product.get(exponent, _sage_const_0 ) - base_product.get(exponent, _sage_const_0 )) % Q
            for exponent in set(product) | set(base_product)
        }
        points.append(BASE.quotient_by_conic(difference, _sage_const_5 , Q))

    affine = matrix(F, [[_sage_const_1 ] * len(orbit)] + [list(column) for column in zip(*points)])
    linear = affine.row_space().basis_matrix()
    translation = translation_permutation()
    unseen = set(orbit)
    translation_orbits = []
    while unseen:
        matching = min(unseen)
        part = []
        current = matching
        while current not in part:
            part.append(current)
            current = BASE.image(translation, current)
        assert len(part) == Q
        translation_orbits.append(part)
        unseen -= set(part)

    orbit_index = {matching: i for i, matching in enumerate(orbit)}
    orbit_sums = matrix(F, len(translation_orbits), len(orbit), sparse=True)
    for row, part in enumerate(translation_orbits):
        for matching in part:
            orbit_sums[row, orbit_index[matching]] = _sage_const_1 
    norm_images = matrix(
        F,
        [
            [
                sum(
                    linear[i, orbit_index[matching]]
                    * linear[j, orbit_index[matching]]
                    for matching in part
                )
                for part in translation_orbits
            ]
            for i in range(linear.nrows())
            for j in range(i, linear.nrows())
        ],
    )
    sheet_sets = [set(sheet) for sheet in sheets]
    orbit_sheet = [
        next(i for i, sheet_set in enumerate(sheet_sets) if part[_sage_const_0 ] in sheet_set)
        for part in translation_orbits
    ]
    sheet_ranks = [
        norm_images[:, [j for j, value in enumerate(orbit_sheet) if value == i]].rank()
        for i in range(_sage_const_2 )
    ]
    rank = norm_images.rank()
    lam = len(sheets[_sage_const_0 ]) // Q
    return {
        "orbit_size": len(orbit),
        "lambda": lam,
        "linear_rank": linear.nrows(),
        "norm_rank": rank,
        "sheet_norm_ranks": sheet_ranks,
        "invariant_trade_dimension": _sage_const_2  * lam - rank,
    }


def main():
    pgl, psl = BASE.projective_groups(Q)
    matchings = sorted(BASE.perfect_matchings(range(Q + _sage_const_1 )))
    representatives = {}
    for orbit in BASE.subgroup_orbits(pgl, matchings):
        sheets = BASE.subgroup_orbits(psl, orbit)
        if len(sheets) == _sage_const_2  and len(orbit) not in representatives:
            representatives[len(orbit)] = (orbit, sheets)
    assert sorted(representatives) == [_sage_const_364 , _sage_const_1092 , _sage_const_2184 ]
    for size in sorted(representatives):
        print(norm_record(*representatives[size]))


if __name__ == "__main__":
    main()

